        value = grid[0][c]
        if value != background and all(grid[r][c] == value for r in range(h)):
            lines.append((None, c, value))
    for r, c, _ in lines:
        if r is not None:
            result[r] = [2] * w
        else:
            for i in range(h):
                result[i][c] = 2
    return result
